import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.BM5YPQmL.js";const k=JSON.parse('{"title":"درس التقنية والبرمجيات","description":"","frontmatter":{},"headers":[],"relativePath":"ar/guide/tutorials/tech.md","filePath":"ar/guide/tutorials/tech.md"}'),l={name:"ar/guide/tutorials/tech.md"};function n(h,e,r,o,d,p){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="درس-التقنية-والبرمجيات" tabindex="-1">درس التقنية والبرمجيات <a class="header-anchor" href="#درس-التقنية-والبرمجيات" aria-label="Permalink to &quot;درس التقنية والبرمجيات&quot;">​</a></h1><p>في هذا الدرس تصنع فيديو موضوعه: شرح الـ rate limiting بخوارزمية token bucket لمطوري الـ backend. ستستخدم الحزمة <code>tech</code> وثيمها <code>default</code>، ويستغرق العمل نحو عشر دقائق قبل التسجيل.</p><h2 id="_1-أنشئ-الحلقة" tabindex="-1">1. أنشئ الحلقة <a class="header-anchor" href="#_1-أنشئ-الحلقة" aria-label="Permalink to &quot;1. أنشئ الحلقة&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rate-limiting</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tech</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system-concept</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ar</span></span></code></pre></div><p>استخدم <code>--lang en</code> لنسخة إنجليزية. وتضم الحزمة أيضاً القالبين <code>latency-numbers</code> و<code>request-path</code>. يعرض <a href="./../../reference/packs.html#tech">فهرس الحزم</a> كل القوالب وحقولها.</p><h2 id="_2-أدخل-بياناتك" tabindex="-1">2. أدخل بياناتك <a class="header-anchor" href="#_2-أدخل-بياناتك" aria-label="Permalink to &quot;2. أدخل بياناتك&quot;">​</a></h2><p>افتح الحلقة بالأمر <code>reelforge edit rate-limiting</code> واستبدل الأسماء والأرقام والكلمة المفتاحية الافتراضية ببياناتك، أو ابدأ من لوحة التحكم (<strong>+ New episode</strong> ثم <strong>Start from template</strong>)، فيطلب النموذج كل حقل على حدة. التزم بحدود الطول الظاهرة لكل حقل.</p><p><strong>الجمهور والنبرة.</strong> المطورون والطلاب والمؤسسون التقنيون. كن دقيقاً وملموساً وخفيف الظل قليلاً.</p><ul><li>استخدم <code>node</code> و<code>arrow</code> مع حزم بيانات متحركة لمسار الطلب، و<code>bucket</code> للمحدِّد.</li><li>اجعل كل عنصر يدخل عند نطق الكلمة التي تسميه: «bucket» و«token» و«429».</li><li>حلقات <code>examples/season1-arabic</code> تعرض مشاهد كاملة بهذا الأسلوب.</li></ul><h2 id="_3-راجع-المحتوى" tabindex="-1">3. راجع المحتوى <a class="header-anchor" href="#_3-راجع-المحتوى" aria-label="Permalink to &quot;3. راجع المحتوى&quot;">​</a></h2><ul><li>الكود يجب أن يكون صحيحاً وقابلاً للتشغيل كما هو، وبحد أقصى 8 أسطر لكل عنصر <code>code</code>.</li><li>لا شعارات شركات أو منتجات حقيقية؛ صِف التقنيات بشكل عام.</li><li>في مواضيع الأمان: اشرح طرق الحماية لا الثغرات العاملة، واستخدم <code>example.com</code>.</li></ul><h2 id="_4-تحقق-وسجّل-وصدّر" tabindex="-1">4. تحقق وسجّل وصدّر <a class="header-anchor" href="#_4-تحقق-وسجّل-وصدّر" aria-label="Permalink to &quot;4. تحقق وسجّل وصدّر&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rate-limiting</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> align</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rate-limiting</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # after you save voice.wav in the episode folder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> render</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rate-limiting</span></span></code></pre></div><p>يوجد مثال مكتمل في <code>packs/tech/examples/rate-limiting-ar</code>؛ صدّره مع الخيار <code>--silent</code> للمقارنة.</p>`,14)])])}const g=a(l,[["render",n]]);export{k as __pageData,g as default};
